mapper.select:
select site_id, region_id, name, region, address, sido, sigungu, eupmyeondong,
contact_phone, create_time
from site
where name = #{name,jdbcType=VARCHAR}
and address = #{address,jdbcType=VARCHAR}
limit 1

select count(*) from site
and region_id = #{regionId}
and (name like concat('%', #{query}, '%') or address like concat('%', #{query}, '%'))
